package com.mfg.plm.controller;import com.mfg.common.api.ApiResponse;import com.mfg.plm.service.EngineeringChangeChainService;import com.mfg.workflow.entity.WfInstance;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/plm") @RequiredArgsConstructor public class EngineeringChangeChainController{private final EngineeringChangeChainService service;
 @GetMapping("/{type:ecrs|ecos}") @PreAuthorize("hasAuthority('PLM:CHANGE:VIEW')") public ApiResponse<Page<Map<String,Object>>>page(@PathVariable String type,@RequestParam(required=false)String keyword,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(service.page(type,keyword,page,size));}@PostMapping("/ecrs") @PreAuthorize("hasAuthority('PLM:ECR:CREATE')") public ApiResponse<Map<String,Object>>createEcr(@RequestBody Map<String,Object>x){return ApiResponse.ok(service.createEcr(x));}@PutMapping("/ecrs/{id}/impact-analysis") @PreAuthorize("hasAuthority('PLM:ECR:UPDATE')") public ApiResponse<List<Map<String,Object>>>impacts(@PathVariable Long id,@RequestBody List<Map<String,Object>>x){return ApiResponse.ok(service.impacts(id,x));}@PostMapping("/ecrs/{id}/create-eco") @PreAuthorize("hasAuthority('PLM:ECO:CREATE')") public ApiResponse<Map<String,Object>>createEco(@PathVariable Long id,@RequestBody Map<String,Object>x){return ApiResponse.ok(service.createEco(id,x));}@PostMapping("/ecos/{id}/submit") @PreAuthorize("hasAuthority('PLM:ECO:SUBMIT')") public ApiResponse<WfInstance>submit(@PathVariable Long id){return ApiResponse.ok(service.submitEco(id));}@PostMapping("/ecos/{id}/create-ecn") @PreAuthorize("hasAuthority('PLM:ECN:CREATE')") public ApiResponse<Map<String,Object>>ecn(@PathVariable Long id){return ApiResponse.ok(service.createEcnFromEco(id));}@PostMapping("/ecns/{id}/implement") @PreAuthorize("hasAuthority('PLM:ECN:IMPLEMENT')") public ApiResponse<Map<String,Object>>implement(@PathVariable Long id){return ApiResponse.ok(service.implement(id));}}
